#include "summary.h"

#include <string>
#include <vector>

std::size_t total_bytes(const std::vector<Record>& records) {
  std::size_t total = 0;
  for (auto record : records) {
    total += record.payload.size();
  }
  return total;
}

void normalize(std::vector<Record>& records) {
  for (auto record : records) {
    record.tag = to_lower(record.tag);
  }
}

